{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "weaken",
  "supportive_card_ids": ["C03", "C15", "C152", "C178", "C203", "C238", "C242"],
  "contradictory_card_ids": ["C197", "C243"],
  "prediction_basis_card_ids": ["C03", "C15", "C152", "C178"],
  "claims": [
    {
      "claim": "Timolol, which shares the tert-butylamino aryloxypropanolamine core, has measured human oral bioavailability of 50-75% (e.g., 61.0 ± 19.2% at 0.4 mg/kg), providing a direct class anchor above the 20% threshold.",
      "card_ids": ["C03", "C15"]
    },
    {
      "claim": "The closest urea-containing analogue pafenolol (M09) shows intestinal secretion in vivo and predominant basolateral-to-apical transport in Caco-2, and celiprolol exposure is increased by the P-gp inhibitor itraconazole without a change in half-life; this is mechanistic evidence for gut-wall efflux in the urea-containing beta-blocker chemotype.",
      "card_ids": ["C197", "C243"]
    },
    {
      "claim": "The L5 efflux findings are not accompanied by any direct F measurement for pafenolol or celiprolol and do not affirmatively establish F < 20%; efflux in the class (e.g., metoprolol ER > 2) can coexist with F well above 20%.",
      "card_ids": ["C197", "C243", "C198"]
    },
    {
      "claim": "Propranolol controls show high, symmetrical permeability and no P-gp efflux, but propranolol lacks the urea/cyclohexyl motif and is less transferable for the efflux question.",
      "card_ids": ["C203", "C238", "C242"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C197", "C243"]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability exists for the query molecule; all evidence is from analogue contexts.",
    "No query-specific P-gp/efflux or intestinal metabolism assay is available; pafenolol and celiprolol are close but not identical to the query.",
    "No direct F value for pafenolol or celiprolol is provided in L5, so the magnitude of any efflux-related loss cannot be calibrated against the 20% threshold.",
    "The strongest high-F anchor (timolol) lacks the urea/cyclohexyl substituent, leaving structural uncertainty."
  ],
  "decision_summary": "L5 adds mechanistic gut-wall efflux evidence for the urea-containing beta-blocker chemotype (pafenolol, celiprolol), which is a negative absorption signal and lowers confidence, but it does not provide direct or threshold-relevant evidence that F < 20%. The high prediction is retained based on timolol's normal-human F of 50-75%, favorable class solubility, and high-permeability aryloxypropanolamine examples; confidence is reduced to low."
}

